package pl.edu.mimuw;public class LinkedList {    private boolean isHead;    private LinkedList next;    private int value;    private int size;    public LinkedList() {        isHead = true;        size = 0;    }    LinkedList added(int value) {        LinkedList newLinkedList = new LinkedList();        newLinkedList.isHead = false;        newLinkedList.value = value;        newLinkedList.next = this;        newLinkedList.size = size + 1;        return newLinkedList;    }    LinkedList removed() {        return next;    }    int read() {        return value;    }    int getSize() {        return size;    }}